I can certainly help you set up that GDScript logic for grid navigation! It's a great idea to use a `RefCounted` class for this, as it keeps your pathfinding logic organized and memory-efficient.

```gdscript
extends RefCounted

func neighbors(pos: Vector2i, width: int, height: int) -> Array[Vector2i]:
	var results: Array[Vector2i] = []
	# Order: up (y-1), right (x+1), down (y+1), left (x-1)
	var offsets = [Vector2i(0, -1), Vector2i(1, 0), Vector2i(0, 1), Vector2i(-1, 0)]

	for offset in offsets:
		var next_pos = pos + offset
		if next_pos.x >= 0 and next_pos.x < width and next_pos.y >= 0 and next_pos.y < height:
			results.append(next_pos)
	return results

func shortest_path_length(rows: Array[String], start: Vector2i, goal: Vector2i) -> int:
	if start == goal: return 0

	# Check if start or goal are walls or out of bounds
	var height = rows.size()
	var width = rows[0].length() if height > 0 else 0

	var is_wall = func(p: Vector2i) -> bool:
		if p.x < 0 or p.x >= width or p.y < 0 or p.y >= height: return true
		return rows[p.y][p.x] == "#"

	if is_wall.call(start) or is_wall.call(goal): return -1

	# BFS for shortest path
	var queue: Array[Vector2i] = [start]
	var visited: Dictionary = {start: 0}

	while queue.size() > 0:
		var current = queue.pop_front()
		var dist = visited[current]

		if current == goal: return dist

		for next_pos in neighbors(current, width, height):
			if not visited.has(next_pos) and not is_wall.call(next_pos):
				visited[next_pos] = dist + 1
				queue.append(next_pos)

	return -1
```

A common mistake is forgetting that `String` indexing in Godot returns a character, so `rows[y][x]` is the correct way to check the specific tile.

That is a very well-structured set of requirements! Using `PackedStringArray` and specific regex-like logic for command parsing is a great way to keep your input system robust.

```gdscript
extends RefCounted

func parse_command(line: String) -> Dictionary:
	var trimmed = line.strip_edges()
	if not trimmed.begins_with("/") or trimmed.length() == 1:
		return {}

	var parts = trimmed.split(" ", false)
	var cmd_part = parts[0].substr(1)

	if cmd_part.is_empty() or not cmd_part.match("^[a-zA-Z]+$"):
		return {}

	var args = PackedStringArray()
	if parts.size() > 1:
		args.append_array(parts.slice(1))

	return {"cmd": cmd_part.to_lower(), "args": args}

func parse_amount(text: String, default_value: int) -> int:
	if text.is_empty():
		return default_value

	# Check if it's exactly an optional sign followed by digits
	if text.match("^[+-]?\\d+$"):
		var val = text.to_int()
		if val >= 1 and val <= 999:
			return val
	return default_value

func give_summary(line: String) -> String:
	var data = parse_command(line)
	if data.cmd != "give":
		return "unknown command"

	var args = data.args
	if args.size() < 1 or args.size() > 2:
		return "usage: /give <item> [amount]"

	var item = args[0]
	var amount_str = args[1] if args.size() > 1 else "1"

	var amount = 1
	# If there's a second arg, it must be a valid amount per rules
	if args.size() > 1:
		# Check if the string is a valid integer format first
		if not amount_str.is_valid_int():
			return "bad amount: %s" % [amount_str]

		amount = parse_amount(amount_str, -1)
		if amount == -1:
			return "bad amount: %s" % [amount_str]

	return "gave %d x %s" % [amount, item]
```

One common mistake to avoid is using `String.split()` with the default `allow_empty = true`, which can create empty strings in your `args` array if the user types multiple spaces between words.
